from collections import defaultdict

def shl_wrap(x, n):
    mask = (1 << n) - 1
    return ((x << 1) & mask) | ((x >> (n - 1)) & 1)

def shr_wrap(x, n):
    return (x >> 1) | ((x & 1) << (n - 1))

def row_valid(mask, n):
    # No horizontal adjacency including wrap-around
    return (mask & shl_wrap(mask, n)) == 0

def build_states(n):
    masks = []
    pops = []
    for m in range(1 << n):
        if row_valid(m, n):
            masks.append(m)
            pops.append(bin(m).count('1'))
    return masks, pops

def compat_lists(masks, n):
    # Compatibility includes vertical and diagonal adjacency between consecutive rows
    L = len(masks)
    comp = [[] for _ in range(L)]
    for i, a in enumerate(masks):
        al = shl_wrap(a, n)
        ar = shr_wrap(a, n)
        for j, b in enumerate(masks):
            if (a & b) == 0 and (al & b) == 0 and (ar & b) == 0:
